{
  "id": "10042",
  "self": "https://workato.atlassian.net/rest/api/3/issue/10042",
  "key": "BUG-4571",
  "fields": {
    "summary": "Workflow execution failures for Acme Corp — retry loop after connector timeout",
    "description": {
      "version": 1,
      "type": "doc",
      "content": [
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Escalated from Zendesk ticket T-1042. Acme Corp workflows failing after 30s timeout in the HTTP connector. The retry policy is producing a loop where each retry re-triggers the timeout, causing runaway job queues."
            }
          ]
        },
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Repro: trigger any workflow that calls the Acme Corp on-prem HTTP endpoint; observe the connector times out at 30s and the recipe enters a retry loop instead of failing cleanly."
            }
          ]
        }
      ]
    },
    "status": {
